package thaumcraft.research;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import com.mojang.serialization.JsonOps;
import com.google.gson.*;
import java.nio.file.*;
import net.minecraft.core.*;
import thaumcraft.essentia.*;
class TransfuserTest {
 @Test void forwardPrismMatchesAllSixOriginalDirections(){var origin=new BlockPos(7,80,-3);for(var f:Direction.values()){assertFalse(RemoteEssentia.contains(origin,origin,f));assertFalse(RemoteEssentia.contains(origin,origin.relative(f,-1),f));assertTrue(RemoteEssentia.contains(origin,origin.relative(f,15),f));assertFalse(RemoteEssentia.contains(origin,origin.relative(f,16),f));var side=f.getAxis()==Direction.Axis.X?Direction.UP:Direction.EAST;assertTrue(RemoteEssentia.contains(origin,origin.relative(side,16),f));assertFalse(RemoteEssentia.contains(origin,origin.relative(side,17),f));}}
 @Test void reservedUnitAndExactTickPhaseSurviveCodec(){var state=new TransfuserState(1,3,"ignis",17);var encoded=TransfuserState.CODEC.encodeStart(JsonOps.INSTANCE,state).getOrThrow();assertEquals(state,TransfuserState.CODEC.parse(JsonOps.INSTANCE,encoded).getOrThrow());assertEquals(0,state.tick().tick().phase());assertEquals("ignis",state.tick().tick().pending());assertEquals(18,state.delivered().transferred());assertTrue(state.delivered().pending().isEmpty());assertEquals(Long.MAX_VALUE,new TransfuserState(1,0,"aer",Long.MAX_VALUE).delivered().transferred());}
 @Test void invalidAndFutureStatesAreRejected(){for(var raw:new String[]{"{version:2,phase:0,pending:'aer',transferred:1}","{version:1,phase:5,pending:'aer',transferred:1}","{version:1,phase:0,pending:'bogus',transferred:1}","{version:1,phase:0,pending:'',transferred:-1}"})assertTrue(TransfuserState.CODEC.parse(JsonOps.INSTANCE,JsonParser.parseString(raw)).error().isPresent());}
 @Test void meshesAndAllSixOrientationsArePreserved()throws Exception{for(var name:new String[]{"essentia_input","essentia_output"}){var old=read("src/main/resources/assets/thaumcraft/models/block/"+name+".json");var modern=read("src/modern/resources/assets/thaumcraft/models/block/"+name+".json");assertEquals(old.get("elements"),modern.get("elements"));var variants=read("src/modern/resources/assets/thaumcraft/blockstates/"+name+".json").getAsJsonObject("variants");assertEquals(6,variants.size());for(var d:Direction.values())assertTrue(variants.has("facing="+d.getName()));}}
 @Test void originalCostsAndBookAliasesUseTheRealDevices()throws Exception{var views=read("src/modern/resources/assets/thaumcraft/knowledge/recipe_views.json");for(var pair:new String[][]{{"essentia_input","EssentiaTransportIn","minecraft:dispenser"},{"essentia_output","EssentiaTransportOut","minecraft:hopper"}}){var r=read("src/modern/resources/data/thaumcraft/recipe/arcane/"+pair[0]+".json");assertEquals(100,r.get("vis").getAsInt());assertEquals("ESSENTIATRANSPORT",r.get("research").getAsString());assertEquals(1,r.getAsJsonObject("crystals").get("aer").getAsInt());assertEquals(1,r.getAsJsonObject("crystals").get("aqua").getAsInt());assertEquals(pair[2],r.getAsJsonObject("recipe").getAsJsonObject("key").get("Q").getAsString());assertEquals("thaumcraft:"+pair[0],views.getAsJsonObject("thaumcraft:"+pair[1]).getAsJsonObject("result").get("id").getAsString());}}
 JsonObject read(String path)throws Exception{return JsonParser.parseString(Files.readString(Path.of(path))).getAsJsonObject();}
}
